#!/usr/bin/env python3
"""A4-PR2 lane C mutation-proof generator (production flips only)."""
import os, shutil, subprocess
PM='packages/runtime/governance/permission-mutation.ts'; SV='packages/runtime/governance/service.ts'
T='packages/runtime/test/a4p2-dual-envelope-mutation.test.ts'
OUT='dev/agent-workflow/evidence/a4-pr2/mutation-proofs/lane-c-mutation-proofs.txt'
lines=[f"# A4-PR2 lane C mutation proofs - generated by generate-lane-c.py.",
       f"# HEAD {subprocess.run(['git','rev-parse','--short','HEAD'],capture_output=True,text=True).stdout.strip()}.",""]
PRIS='/tmp/lane-c-pristine.bin'
def run(label, path, old, new):
    src=open(path).read()
    if not os.path.exists(PRIS): shutil.copyfile(path, PRIS)
    if src.count(old)!=1:
        lines.append(f"## {label}\n- ANCHOR ERROR count={src.count(old)} - proof not run\n"); open(OUT,'w').write('\n'.join(lines)); return False
    open(path,'w').write(src.replace(old,new))
    p=subprocess.run(['npx','vitest','run',T,'packages/runtime/test/a3p3-permission-mutation-authority.test.ts'],capture_output=True,text=True)
    tail=[l.strip() for l in (p.stdout+p.stderr).split('\n') if l.strip().startswith('Tests ')]
    failed=p.returncode!=0
    lines.append(f"## {label}\n- file: {path}\n- flip: {old.strip()[:80]!r}\n- result: {tail[0] if tail else 'no summary'}\n- verdict: {'RED (the suite noticed)' if failed else 'GREEN (NOTHING NOTICED)'}\n- caught: {failed}\n")
    open(OUT,'w').write('\n'.join(lines)); shutil.copyfile(PRIS, path); os.remove(PRIS); return failed
r=[]
r.append(run('C1 the ceiling gate was never called from the service',SV,"          authorizeCeilingBoundedPermissionRise(ceilingClassification.rising, (region) => authorityCeilingJudge(ceilingContext, region))","          void ceilingClassification"))
r.append(run('C2 the kernel refused `insufficient` BEFORE `unavailable`/`undetermined`',PM,"  for (const { region, verdict } of verdicts) {\n    if (verdict.status !== 'unavailable') continue","  for (const { region, verdict } of verdicts) {\n    if (verdict.status !== 'insufficient') continue"))
r.append(run('C3 the insufficient refusal reused the Alpha.3 EXPANSION code',PM,"      PERMISSION_MUTATION_ERROR_CODES.AUTHORITY_CEILING_INSUFFICIENT,\n      'authority-ceiling-insufficient',","      PERMISSION_MUTATION_ERROR_CODES.EXPANSION_OUTSIDE_ENVELOPE,\n      'expansion-region-uncovered',"))
r.append(run('C4 an unreadable ceiling document was refused as insufficient (widen-avoided-but-misrouted)',PM,"      PERMISSION_MUTATION_ERROR_CODES.EFFECT_CONTEXT_UNAVAILABLE,\n      'authority-ceiling-document-unavailable',","      PERMISSION_MUTATION_ERROR_CODES.AUTHORITY_CEILING_INSUFFICIENT,\n      'authority-ceiling-document-unavailable',"))
r.append(run('C5 the kernel treated an undetermined ceiling as sufficient',PM,"    if (verdict.status !== 'undetermined') continue","    if (true) continue"))
r.append(run('C6 the exported judge read `no-authority` as an unrestricted ceiling',SV,"            if (ceiling.status === 'no-authority') {","            if (false) {"))
r.append(run('C7 the exported judge consulted ONE plane only (the fused-lookup regression)',SV,"            ['expansion', expansion] as const,\n            ['approval', approval] as const,","            ['expansion', expansion] as const,"))
lines.append(f"\n# SUMMARY: {sum(r)}/{len(r)} mutations were caught by the suite\n")
open(OUT,'w').write('\n'.join(lines)); print(f"{sum(r)}/{len(r)} caught")
